	Zabbix.log(5, '[ Mattermost Webhook ] Call {0}({1})'.format(
		arguments.callee.name,
		JSON.stringify(arguments)
	));

	var teamUser = send_to
			.trim()
			.split('/@'),
		bot = getBotUser(),
		user = getUserByName(teamUser[1]);

