				contentUrl: null,
				content: {
					$schema: "http://adaptivecards.io/schemas/adaptive-card.json",
					type: "AdaptiveCard",
					version: "1.4",
					body: [
						{
							type: "Container",
							items: [
								{
									type: "TextBlock",
									size: "Medium",
									wrap: "true",
									weight: "Bolder",
									text: this.params.alert_subject
								}
							],
							style: "",
							bleed: true
						}
					],
					actions: [
						{
							type: "Action.OpenUrl",
