		],
		severities = [
			{name: 'not_classified', color: '#97AAB3'},
			{name: 'information', color: '#7499FF'},
			{name: 'warning', color: '#FFC859'},
			{name: 'average', color: '#FFA059'},
			{name: 'high', color: '#E97659'},
